import org.eclipse.rdf4j.rio.RDFFormat;
import org.eclipse.rdf4j.sail.lmdb.LmdbStore;
import org.eclipse.rdf4j.sail.lmdb.bulk.BulkLoadPhase;
import org.eclipse.rdf4j.sail.lmdb.bulk.LmdbBulkLoader;
import org.eclipse.rdf4j.sail.lmdb.bulk.ProgressSnapshot;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;

/**
 * Command-line scale harness for the LMDB bulk loader. It generates a deterministic N-Quads file, loads it with the
 * bulk loader (mode {@code bulk}) or one ordinary transaction (mode {@code tx}), and prints per-phase wall time, total
 * throughput and the peak number of files in the bulk-load workspace.
 *
 * <p>
 * Arguments: {@code mode statements scenario dataDirectory [workers] [memoryBudgetMiB]}. The scenario is
 * {@code realistic} (eight statements per entity, half of them in named graphs) or {@code representative} (the mix used
 * by {@link LmdbBulkLoadBenchmark}). Generated inputs are cached in the data directory by name.
 * </p>
 */
public final class LmdbBulkLoadScaleHarness {

	private LmdbBulkLoadScaleHarness() {
	}

	public static void main(String[] args) throws Exception {
		if (args.length < 4) {
			System.err
					.println("usage: bulk|tx statements realistic|representative dataDirectory [workers] [memoryMiB]");
			System.exit(2);
		}
		String mode = args[0];
		int statements = Integer.parseInt(args[1]);
		String scenario = args[2];
		Path dataDirectory = Path.of(args[3]).toAbsolutePath();
		int workers = args.length > 4 ? Integer.parseInt(args[4]) : 0;
		long memoryBudgetMiB = args.length > 5 ? Long.parseLong(args[5]) : 0L;

		Files.createDirectories(dataDirectory);
		Path input = dataDirectory.resolve(scenario + "-" + statements + ".nq");
		if (!Files.exists(input)) {
			long generationStarted = System.nanoTime();
			generate(input, statements, scenario);
			System.out.printf("generated %s (%,d bytes) in %,d ms%n", input, Files.size(input),
					(System.nanoTime() - generationStarted) / 1_000_000L);
		}
		System.out.printf("input %s (%,d bytes)%n", input, Files.size(input));

		Path store = dataDirectory.resolve("store-" + mode);
		Path workspace = dataDirectory.resolve(".store-" + mode + ".lmdb-bulk-load");
		deleteRecursively(store);
		deleteRecursively(workspace);
		Files.deleteIfExists(dataDirectory.resolve("store-" + mode + ".lmdb-bulk-load.properties"));

		LmdbStoreConfig config = new LmdbStoreConfig();
		System.out.printf("tripleIndexes=%s maxHeap=%,d MiB cpus=%d%n", config.getTripleIndexes(),
				Runtime.getRuntime().maxMemory() >> 20, Runtime.getRuntime().availableProcessors());

		long started = System.nanoTime();
		try (FileCountSampler sampler = new FileCountSampler(workspace)) {
			if ("bulk".equals(mode)) {
				PhaseTimer timer = new PhaseTimer(started);
				LmdbBulkLoader.Builder builder = LmdbBulkLoader.builder(store, config)
						.progressListener(timer::onProgress);
				if (workers > 0) {
					builder.workers(workers);
				}
				if (memoryBudgetMiB > 0) {
					builder.memoryBudgetBytes(memoryBudgetMiB * 1024L * 1024L);
				}
				LmdbBulkLoader.Result result = builder.build().load(input, RDFFormat.NQUADS);
				timer.printSummary();
				System.out.println("result " + result);
			} else if ("tx".equals(mode)) {
				loadTransactionally(store, config, input);
			} else {
				throw new IllegalArgumentException("Unknown mode " + mode);
			}
			System.out.printf("PEAK workspace files: %,d%n", sampler.peak());
		}
		long elapsedMillis = Math.max(1L, (System.nanoTime() - started) / 1_000_000L);
		System.out.printf("TOTAL %s %,d statements: %,d ms (%,.0f stmt/s), store=%,d bytes%n", mode, statements,
				elapsedMillis, statements * 1000.0 / elapsedMillis, size(store));
	}

	private static void loadTransactionally(Path store, LmdbStoreConfig config, Path input) throws IOException {
		SailRepository repository = new SailRepository(new LmdbStore(store.toFile(), config));
		repository.init();
		try (RepositoryConnection connection = repository.getConnection();
				InputStream stream = Files.newInputStream(input)) {
			long started = System.nanoTime();
			connection.begin();
			connection.add(stream, input.toUri().toString(), RDFFormat.NQUADS);
			long added = System.nanoTime();
			connection.commit();
			System.out.printf("add %,d ms, commit %,d ms, size %,d%n", (added - started) / 1_000_000L,
					(System.nanoTime() - added) / 1_000_000L, connection.size());
		} finally {
			repository.shutDown();
		}
	}

	private static final class PhaseTimer {
		private final long origin;
		private final Map<BulkLoadPhase, Long> starts = new EnumMap<>(BulkLoadPhase.class);
		private final Map<BulkLoadPhase, Long> ends = new EnumMap<>(BulkLoadPhase.class);
		private BulkLoadPhase current;
		private long lastPrint;

		private PhaseTimer(long origin) {
			this.origin = origin;
		}

		private synchronized void onProgress(ProgressSnapshot snapshot) {
			long now = System.nanoTime();
			if (snapshot.phase() != current) {
				current = snapshot.phase();
				starts.putIfAbsent(current, now);
				System.out.printf("[%8.1fs] start %s%n", seconds(now), current);
			}
			if (snapshot.phaseComplete()) {
				ends.put(snapshot.phase(), now);
				System.out.printf("[%8.1fs] done  %s in %,d ms (ops=%,d)%n", seconds(now), snapshot.phase(),
						(now - starts.getOrDefault(snapshot.phase(), now)) / 1_000_000L, snapshot.phaseOperations());
			} else if (now - lastPrint > TimeUnit.SECONDS.toNanos(5)) {
				lastPrint = now;
				System.out.printf("[%8.1fs]   %s ops=%,d current=%,.0f/s average=%,.0f/s%n", seconds(now),
						snapshot.phase(), snapshot.phaseOperations(), snapshot.currentOperationsPerSecond(),
						snapshot.averageOperationsPerSecond());
			}
		}

		private synchronized void printSummary() {
			System.out.println("phase summary (ms):");
			for (BulkLoadPhase phase : BulkLoadPhase.values()) {
				Long begin = starts.get(phase);
				if (begin != null) {
					long end = ends.getOrDefault(phase, System.nanoTime());
					System.out.printf("  %-28s %,10d%n", phase, (end - begin) / 1_000_000L);
				}
			}
		}

		private double seconds(long now) {
			return (now - origin) / 1e9;
		}
	}

	private static final class FileCountSampler implements AutoCloseable {
		private final Path root;
		private final AtomicLong peak = new AtomicLong();
		private final Thread thread;
		private volatile boolean running = true;

		private FileCountSampler(Path root) {
			this.root = root;
			thread = Thread.ofPlatform().daemon().name("bulk-harness-file-sampler").start(this::run);
		}

		private void run() {
			while (running) {
				peak.accumulateAndGet(countFiles(), Math::max);
				LockSupport.parkNanos(TimeUnit.SECONDS.toNanos(1));
			}
		}

		private long countFiles() {
			if (!Files.isDirectory(root)) {
				return 0L;
			}
			try (Stream<Path> paths = Files.walk(root)) {
				return paths.filter(Files::isRegularFile).count();
			} catch (IOException | UncheckedIOException e) {
				// Files disappear while the loader works; a missed sample is harmless.
				return 0L;
			}
		}

		private long peak() {
			return peak.get();
		}

		@Override
		public void close() throws InterruptedException {
			running = false;
			thread.interrupt();
			thread.join();
		}
	}

	static void generate(Path file, int statements, String scenario) throws IOException {
		try (BufferedWriter writer = Files.newBufferedWriter(file, StandardCharsets.UTF_8,
				StandardOpenOption.CREATE_NEW)) {
			if ("representative".equals(scenario)) {
				for (int index = 0; index < statements; index++) {
					writer.write(LmdbBulkLoadBenchmark.Scenario.REPRESENTATIVE.statement(index));
				}
				return;
			}
			if (!"realistic".equals(scenario)) {
				throw new IllegalArgumentException("Unknown scenario " + scenario);
			}
			int entities = statements / 8;
			String ex = "http://example.org/";
			String xsd = "http://www.w3.org/2001/XMLSchema#";
			for (int i = 0; i < entities; i++) {
				String subject = "<" + ex + "entity/" + i + ">";
				String graph = (i & 1) == 0 ? "" : " <" + ex + "graph/" + (i % 16) + ">";
				writer.write(subject + " <http://www.w3.org/1999/02/22-rdf-syntax-ns#type> <" + ex + "class/C"
						+ (i % 40) + ">" + graph + " .\n");
				writer.write(subject + " <http://www.w3.org/2000/01/rdf-schema#label> \"Entity number " + i + "\"@en"
						+ graph + " .\n");
				writer.write(subject + " <" + ex + "name> \"name-" + Integer.toHexString(i * 0x9E3779B1) + "\""
						+ graph + " .\n");
				writer.write(subject + " <" + ex + "age> \"" + (i % 90) + "\"^^<" + xsd + "integer>" + graph + " .\n");
				writer.write(subject + " <" + ex + "created> \"20" + (10 + i % 15) + "-" + pad(1 + i % 12) + "-"
						+ pad(1 + i % 28) + "T" + pad(i % 24) + ":" + pad(i % 60) + ":" + pad((i / 60) % 60) + "Z\"^^<"
						+ xsd + "dateTime>" + graph + " .\n");
				writer.write(subject + " <" + ex + "knows> <" + ex + "entity/" + Math.floorMod(i * 7919L + 13, entities)
						+ ">" + graph + " .\n");
				writer.write(subject + " <" + ex + "memberOf> <" + ex + "group/" + (i % 5000) + ">" + graph + " .\n");
				writer.write(subject + " <" + ex + "description> \"A somewhat longer free-text description for entity "
						+ i + " which mentions group " + (i % 5000) + " and class C" + (i % 40) + ".\"" + graph
						+ " .\n");
			}
		}
	}

	private static String pad(int value) {
		return value < 10 ? "0" + value : Integer.toString(value);
	}

	private static void deleteRecursively(Path root) throws IOException {
		if (!Files.exists(root)) {
			return;
		}
		try (Stream<Path> paths = Files.walk(root)) {
			for (Path path : paths.sorted(Comparator.reverseOrder()).toList()) {
				Files.delete(path);
			}
		}
	}

	private static long size(Path root) throws IOException {
		if (!Files.exists(root)) {
			return 0L;
		}
		try (Stream<Path> paths = Files.walk(root)) {
			return paths.filter(Files::isRegularFile).mapToLong(path -> path.toFile().length()).sum();
		}
	}
}
